function Ad({ h, text, tone }: { h: number; text: string; tone: string }) {
  return (
    <div data-d="ad" className="relative my-2 overflow-visible" style={{ height: h }}>
      <div
        data-d="ad-face"
        className="absolute inset-0 flex items-center justify-between rounded-md px-3 text-[10px] font-black uppercase text-white"
        style={{ background: tone }}
      >
        <span>{text}</span>
        <span className="rounded bg-white/90 px-1.5 py-0.5 text-[8px] text-black">AD</span>
      </div>
      <div className="pointer-events-none absolute inset-0 grid grid-cols-4 grid-rows-2">
        {Array.from({ length: 8 }, (_, index) => (
          <span key={index} data-d="shard" className="opacity-0" style={{ background: tone }} />
        ))}
      </div>
    </div>
  )
}

const build: Build = ({
  tl,
  q,
  qa,
  step,
  final,
  move,
  click,
  count,
  scramble,
  wait,
  cursorOut,
}) => {
  step(0)
  tl.from(
    qa('ad'),
    { scale: 0.6, opacity: 0, duration: 0.6, stagger: 0.15, ease: 'back.out(2.5)' },
    0.2,
  )
  tl.from(qa('pixel'), { scale: 0, duration: 0.4, stagger: 0.08, ease: 'back.out(3)' }, '<0.2')

  step(1, '+=0.4')
  move('toggle')
  click('toggle')
  tl.to(q('toggle-fill'), { opacity: 1, duration: 0.2 }, '<')
  tl.to(q('toggle-knob'), { x: 12, duration: 0.25 }, '<')
  tl.fromTo(
    q('pulse'),
    { scale: 0.6, opacity: 0.8 },
    { scale: 2.2, opacity: 0, duration: 0.8, ease: 'power2.out' },
    '<',
  )
  tl.to(q('shield'), { color: '#4ade80', duration: 0.3 }, '<')
  scramble('status', 'Protected', { at: '<', duration: 0.5 })
  cursorOut('<0.2')

  step(2, '+=0.2')
  tl.set(qa('shard'), { opacity: 1 })
  tl.set(qa('ad-face'), { opacity: 0 })
  const burst = tl.duration()
  qa('shard').forEach((shard) => {
    tl.to(
      shard,
      {
        physics2D: {
          velocity: gsap.utils.random(140, 300),
          angle: gsap.utils.random(200, 340),
          gravity: 900,
        },
        rotation: gsap.utils.random(-260, 260),
        opacity: 0,
        duration: 1.1,
        ease: 'none',
      },
      burst,
    )
  })
  tl.to(qa('pixel'), { scale: 0, opacity: 0, duration: 0.3, stagger: 0.05 }, burst)
  count('blocked', 27, { at: '<', duration: 1.1 })
  tl.to(
    qa('ad'),
    { height: 0, marginTop: 0, marginBottom: 0, duration: 0.6, ease: 'expo.inOut' },
    '-=0.4',
  )

  step(3, '+=0.3')
  tl.fromTo(
    qa('stat-bar'),
    { scaleX: 0 },
    { scaleX: 1, duration: 0.8, stagger: 0.12, ease: 'expo.out' },
  )
  STATS.forEach((stat, index) =>
    count(`stat-${index}`, stat.value, { at: index === 0 ? '<' : '<0.12', duration: 0.8 }),
  )
  final('+=0.4')
  wait(1.6)
}

